parameters.functionCode:
// Build comprehensive context for Claude
const customerData = $('Get Customer Data').item.json;
const recentTickets = $('Get Recent Support Tickets').all();
const knowledgeBase = $('Search A.R.C.H.I.E. Support KB').item.json;

// Format recent tickets
const ticketHistory = recentTickets.map((ticket, idx) => 
  `Ticket ${idx + 1}: ${ticket.json.intent} - ${ticket.json.outcome || 'Resolved'}`
).join('\n');

// Format knowledge base results
const kbContext = knowledgeBase.results?.map(result => 
  `- ${result.title}: ${result.content}`
).join('\n') || 'No specific KB articles found';

return {
  json: {
    customerName: customerData.customer_name || 'Customer',
    customerTier: customerData.customer_tier || 'standard',
    ticketHistory: ticketHistory || 'No previous tickets',
    knowledgeContext: kbContext,
    conversationId: items[0].json.conversationId
  }
};

parameters.jsonBody:
={
  "message": "I need to help a customer with a support inquiry. Please provide an initial response based on the context below.

Customer: {{ $json.customerName }} ({{ $json.customerTier }} tier)
Recent History:
{{ $json.ticketHistory }}

Knowledge Base:
{{ $json.knowledgeContext }}

Provide a helpful, professional initial response. If the issue seems complex or requires technical expertise beyond Tier 1 support, recommend escalation.",
  "context": {
    "conversationId": "{{ $json.conversationId }}",
    "agentType": "support_tier1"
  },
  "useLocalModel": true
}

parameters.functionCode:
// Analyze if escalation needed based on A.R.C.H.I.E.'s response
const response = $('A.R.C.H.I.E. Chat Response').item.json.response;
const metadata = $('A.R.C.H.I.E. Chat Response').item.json.metadata || {};

const escalationKeywords = [
  'escalate', 'complex', 'advanced', 'tier 2', 
  'technical team', 'specialist', 'engineer'
];

const needsEscalation = escalationKeywords.some(keyword => 
  response.toLowerCase().includes(keyword)
) || metadata.confidence < 0.6;

let escalationReason = 'Standard resolution';
if (needsEscalation) {
  if (metadata.confidence < 0.6) {
    escalationReason = 'Low confidence in solution - requires specialist review';
  } else {
    escalationReason = 'Complex technical issue requiring Tier 2/3 expertise';
  }
}

return {
  json: {
    ...items[0].json,
    response: response,
    shouldEscalate: needsEscalation,
    escalationReason: escalationReason,
    confidence: metadata.confidence || 0.8
  }
};

parameters.responseBody:
={{ JSON.stringify({ 
  status: 'success',
  response: $json.response,
  escalated: $json.shouldEscalate || false,
  confidence: $json.confidence,
  agentType: 'archie_tier1'
}) }}
